// Identify which sensor sent the value
let sensor = msg.topic;

// Extract Modbus register value
let value = msg.payload[0] / 10.0;

// Save into flow memory
flow.set(sensor, value);

// Load stored values
let compressor = flow.get("compressor");
let blower = flow.get("blower");
let environment = flow.get("environment");

// Require all 3 before sending
if (compressor === undefined || blower === undefined || environment === undefined) {
    return null;
}

// Build timestamp
function pad(n) { return n.toString().padStart(2, "0"); }

let now = new Date();
let timestamp =
    now.getFullYear() + "-" +
    pad(now.getMonth() + 1) + "-" +
    pad(now.getDate()) + " " +
    pad(now.getHours()) + ":" +
    pad(now.getMinutes()) + ":" +
    pad(now.getSeconds());

// BeaverIoT compatible payload - FLAT structure matching template
msg.payload = {
    device_id: "Compressor1",
    device_name: "Compressor System",

    compressor_temperature: compressor,
    blower_temperature: blower,
    environment_temperature: environment,

    status: 1,
    time: timestamp
};

// Clear values after successful send to prevent stale data
flow.set("compressor", undefined);
flow.set("blower", undefined);
flow.set("environment", undefined);

return msg;

// 1. Set the Header (So Flask knows it's JSON)
msg.headers = { 'Content-Type': 'application/json' };

// 2. Get the Temperature value
// (Assuming your Modbus Read outputs an array, and the value is at index 1)
// If your Modbus node output is just [245], change index to [0]
var raw_value = msg.payload[0]; 
var temperature = raw_value / 10.0;

// 3. Create the JSON Object (The critical fix)
// We UPDATE msg.payload, we do NOT replace 'msg'
msg.payload = {
    "temperature": temperature
};

return msg;

// Extract all 4 values from Python
var health = msg.payload.health;
var critical_incidents = msg.payload.critical_events; 
var raw_anomalies = msg.payload.total_anomalies; // <--- The new raw count
// --- OUTPUT 1: Status ---
var color = "green";
if (health === "WARNING") color = "#ffbf00"; // Yellow
if (health === "CRITICAL") color = "red";    // Red
var msg1 = { payload: health, color: color };

// --- OUTPUT 2: Total Anomalies ---
var msg2 = { payload: raw_anomalies };

// --- OUTPUT 3: Critical Incidents ---
var msg3 = { payload: critical_incidents };

return [msg1, msg2, msg3];

// Output 1: Actual Temperature (Always exists)
var msg1 = { payload: msg.payload.temperature };

// Output 2: Forecast (Only exists after buffering is done)
var msg2 = null;

// Check if forecast exists before trying to send it
if (msg.payload.forecast !== undefined) {
    msg2 = { payload: msg.payload.forecast };
}

// If msg2 is null, Node-RED sends nothing on the second wire
return [msg1, msg2];

// Check if the system is still buffering (warming up)
if (msg.payload.status === "buffering") {
    msg.payload = "⏳ WARMING UP...";
    msg.color = "#ffbf00"; // Amber color for waiting
}
// Check if the forecast exists (Success state)
else if (msg.payload.forecast !== undefined) {
    msg.payload = msg.payload.forecast + " °C";
    msg.color = "#00bcd4"; // Cyan/Blue color for normal
}
// Fallback for errors
else {
    msg.payload = "--.-";
    msg.color = "gray";
}

return msg;

var current = msg.payload.temperature;

// 1. Get the current date as a string (e.g., "2023-10-27")
var now = new Date();
var todayDate = now.toISOString().split('T')[0];

// 2. Retrieve the last saved date
var lastDate = flow.get('last_process_date');

// 3. Initialize variables
var max, min;

// CHECK: Is it a new day? OR is this the first time running?
if (todayDate !== lastDate) {
    // It is a new day! Reset max and min to the CURRENT temperature
    max = current;
    min = current;

    // Save the new date so we know we've handled today
    flow.set('last_process_date', todayDate);
} else {
    // It is the same day. Retrieve existing values.
    max = flow.get('daily_max');
    min = flow.get('daily_min');

    // Safety check: if memory was wiped manually, treat as current
    if (max === undefined) max = current;
    if (min === undefined) min = current;

    // Standard comparison logic
    if (current > max) max = current;
    if (current < min) min = current;
}

// 4. Save the values back to memory
flow.set('daily_max', max);
flow.set('daily_min', min);

// 5. Output
msg.payload = { 
    max: max, 
    min: min, 
    date: todayDate 
};

return msg;

var now = new Date();
// Format: HH:MM:SS
var timeString = now.toLocaleTimeString();
msg.payload = "Last Sync: " + timeString;
